            unique = []
            for k in issues:
                if k not in seen:
                    unique.append(k); seen.add(k)
            line = fn_node.start_point[0] + 1
            joined = ", ".join(unique)
            print(f"    - {rel}:{line} {fn_name}: {joined}")
' 2>/dev/null || true
